const KEY="wwm-ultimate-companion-v1";
const initial={quests:[],journal:[],checks:{},checkUpdatedAt:{},builds:[],mapNotes:[],deletedMapNoteIds:[]};
let data={...initial,...JSON.parse(localStorage.getItem(KEY)||"{}")};if(!Array.isArray(data.mapNotes))data.mapNotes=[];if(!Array.isArray(data.deletedMapNoteIds))data.deletedMapNoteIds=[];if(!data.checkUpdatedAt||typeof data.checkUpdatedAt!=="object")data.checkUpdatedAt={};
const view=document.querySelector("#view"),title=document.querySelector("#page-title");
const labels={overview:"Vue d'ensemble",map:"Carte & découvertes",quests:"Quêtes & objectifs",bosses:"Boss & stratégies",builds:"Builds & équipement",codex:"Encyclopédie",journal:"Journal d'aventure",account:"Mon compte"};
function save(){localStorage.setItem(KEY,JSON.stringify(data));const state=document.querySelector("#save-state");if(state)state.textContent="● Progression sauvegardée";if(window.wwmCloudSave)window.wwmCloudSave(data);}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));}
function shell(){const done=Object.values(data.checks).filter(Boolean).length;return `<div class="grid stats"><div class="card"><div class="stat-label">OBJECTIFS NOTÉS</div><div class="stat-value">${data.quests.length}</div><div class="stat-note">Dans ton carnet</div></div><div class="card"><div class="stat-label">DÉCOUVERTES COCHÉES</div><div class="stat-value">${done}</div><div class="stat-note">Suivi personnel</div></div><div class="card"><div class="stat-label">ENTRÉES DE JOURNAL</div><div class="stat-value">${data.journal.length}</div><div class="stat-note">Tes aventures</div></div><div class="card"><div class="stat-label">BUILDS ENREGISTRÉS</div><div class="stat-value">${data.builds.length}</div><div class="stat-note">Tes configurations</div></div></div>`;}
function overview(){return shell()+`<div class="card hero"><span class="tag">COMPAGNON MULTIPLATEFORME</span><h2>Ton voyage, tes découvertes.</h2><p>Un espace unique et multiplateforme pour organiser ton aventure : repérer tes objectifs, consigner tes trouvailles et préparer tes combats. À terme, ton compte compagnon synchronisera tes données entre appareils.</p><div class="action-row"><button class="btn primary" data-go="map">Ouvrir la carte</button><button class="btn" data-go="journal">Ajouter au journal</button></div></div><div class="grid split"><div><div class="section-head"><h2>À faire ensuite</h2><span class="muted small">Tes objectifs</span></div><div class="card">${data.quests.length?questList():'<div class="empty">Aucun objectif pour le moment. Ajoute une quête ou un rappel.</div>'}</div></div><div><div class="section-head"><h2>Important</h2></div><div class="notice">Le compte compagnon, la synchronisation cloud et le suivi automatique en direct ne sont pas encore activés. Ils seront ajoutés séparément, avec des connecteurs autorisés selon les plateformes. La carte et le suivi manuel restent indépendants de ces connexions.</div></div></div>`;}
function questList(){return '<div class="list">'+data.quests.slice(-5).reverse().map((q,i)=>`<div class="list-row"><span>${esc(q.name)}</span><label class="small"><input type="checkbox" data-quest="${data.quests.length-1-i}" ${q.done?'checked':''}> terminée</label></div>`).join('')+'</div>'}

const regionMilestones=[
{region:"Hexi · Jade Gate Pass",version:"1.4",steps:["Terminer la campagne Qinghe Still Shore","Atteindre le niveau 14","Terminer le chapitre Hexi By Lamplight — Rendezvous"],note:"Ouvre la première zone d’Hexi."},
{region:"Hexi · Liangzhou",version:"1.5",steps:["Terminer la campagne Whitecrown Fortress","Accepter le Lost Chapter Ten Through the Pass"],note:"Débloque Liangzhou et ses trois boss mondiaux."},
{region:"Hexi · Qinchuan",version:"1.6",steps:["Terminer la campagne de Liangzhou Dasan Pass","Lancer la quête d’exploration Hues of a Hidden World"],note:"Débloque Qinchuan et Snowplum Requiem."},
{region:"Kaifeng · Imperial Palace",version:"1.7",steps:["Atteindre le niveau 32","Terminer Kaifeng Main Chapter I — New Arrival in Kaifeng: The Welcoming Crowd","Accepter le Lost Chapter Throne and Tempest I"],note:"Ouvre le palais impérial, Cat Emperor et Gilded Lament."},
{region:"Hidden Mountain",version:"2.0",steps:["Terminer Kaifeng Main Chapter I — New Arrival in Kaifeng: The Welcoming Crowd","Atteindre le niveau 32","Terminer le chapitre Bringer of Embers — Haven Astray"],note:"Débloque Hidden Mountain, Ci & Cuo et Ironheart Centipede."},
{region:"Hidden Mountain · Heaven’s Threshold",version:"2.1",steps:["Atteindre le niveau 32","Terminer le Jianghu Legacy Volume I — Mountain Unveiled","Vérifier l’ouverture serveur Cloudtop Ascent"],note:"Condition d’accès indiquée pour Heaven’s Threshold ; l’ouverture Cloudtop Ascent dépend aussi de la progression du serveur."},
{region:"Qingzhou · Eastern Peak et Penglai",version:"2.3",steps:["Atteindre le niveau 32","Terminer Qinghe Main Chapter — Heaven Has No Pier","Accepter le Lost Chapter Away to Qingzhou"],note:"Débloque Eastern Peak, Penglai et les trois boss mondiaux de Qingzhou."},
{region:"Hidden Mountain · Hutuo",version:"2.4",steps:["Atteindre le niveau 32","Terminer Kaifeng Main Chapter — New Arrival in Kaifeng","Accepter puis terminer le Lost Chapter Hutuo Memories"],note:"Débloque la région Hutuo et les boss Wayfarer Bingshen et Yelu Abuli."}
];

function quests(){const milestones=regionMilestones.map(r=>'<article class="card"><div class="section-head" style="margin:0 0 8px"><h3>'+esc(r.region)+'</h3><span class="tag">v'+esc(r.version)+'</span></div><p class="muted small">'+esc(r.note)+'</p><div class="list">'+r.steps.map(step=>{const existing=data.quests.find(q=>q.name===step);return '<div class="list-row"><span class="small">'+esc(step)+'</span><button class="btn" data-quest-add="'+esc(step)+'" '+(existing?'disabled':'')+'>'+(existing?(existing.done?'Terminé':'Ajouté'):'Ajouter')+'</button></div>';}).join("")+'</div></article>').join("");return '<div class="card"><span class="tag">PROGRESSION DU MONDE</span><h2 style="margin:12px 0">Déblocage des régions</h2><p class="muted small">Ajoute les prérequis à ton carnet, puis coche-les à mesure que tu avances. Les conditions ci-dessous suivent les guides de régions recoupés avec les aperçus de version ; vérifie toujours le Journal en jeu si une étape a changé.</p><div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(250px,1fr));margin-top:14px">'+milestones+'</div><div class="action-row"><a class="btn" href="https://senseos.gg/wiki/where-winds-meet/regions/" target="_blank" rel="noopener">Sources et conditions régionales ↗</a></div></div><div class="card" style="margin-top:16px"><h2>Mon carnet d’objectifs</h2><p class="muted small">Ajoute aussi tes quêtes, tâches et rappels personnels.</p><form id="quest-form" class="form-row"><input class="field" name="name" placeholder="Ex. Terminer une quête / explorer une zone" required><button class="btn primary">Ajouter</button></form><div style="margin-top:18px">'+(data.quests.length?'<div class="list">'+data.quests.slice().reverse().map((q,i)=>'<div class="list-row"><span>'+esc(q.name)+'</span><label class="small"><input type="checkbox" data-quest="'+(data.quests.length-1-i)+'" '+(q.done?'checked':'')+'> terminée</label></div>').join("")+'</div>':'<div class="empty">Ton carnet est vide. Tu peux ajouter les prérequis des régions ci-dessus.</div>')+'</div></div>';}
function map(){
const mapOptions=[{id:"central",label:"Plaine centrale · Qinghe, Kaifeng, Hidden Mountain, Qingzhou et Hutuo",url:"https://wherewindsmeet.th.gl/maps/Central%20Plain"},{id:"hexi",label:"Hexi · Jade Gate Pass, Liangzhou et Qinchuan",url:"https://wherewindsmeet.th.gl/maps/Hexi"},{id:"transdust",label:"Ruines Transdust · carte d'événement",url:"https://wherewindsmeet.th.gl/maps/Transdust%20Ruins"}];
const selected=mapOptions.find(x=>x.id===(data.mapRegion||"central"))||mapOptions[0];
const notes=(data.mapNotes||[]).filter(n=>n.region===selected.id);
const categories=["Coffre","Secret","Ressource","Boss","Point d'intérêt","Autre"];
const optionsHtml=mapOptions.map(x=>'<option value="'+x.id+'" '+(x.id===selected.id?"selected":"")+'>'+esc(x.label)+'</option>').join("");
const checksHtml=["Coffres","Secrets","Ressources","Boss","Points d'intérêt"].map(c=>'<label class="check-row"><input type="checkbox" data-check="'+c+'" '+(data.checks[c]?"checked":"")+'> '+c+'</label>').join("");
const categoriesHtml=categories.map(c=>'<option>'+c+'</option>').join("");
const notesHtml=notes.length?notes.slice().reverse().map(n=>'<div class="list-row"><div style="min-width:0"><label class="small"><input type="checkbox" data-map-note-toggle="'+esc(n.id)+'" '+(n.done?"checked":"")+'> <b>'+esc(n.title)+'</b></label><div class="muted small">'+esc(n.category||"Autre")+(n.detail?" · "+esc(n.detail):"")+'</div></div><button class="btn" data-map-note-delete="'+esc(n.id)+'" aria-label="Supprimer '+esc(n.title)+'">Supprimer</button></div>').join(""):'<div class="empty">Aucune découverte notée pour cette région.</div>';
return `<div class="notice">Carte interactive fournie par TH.GL, un service communautaire indépendant. Elle s'affiche ici après ton clic ; ses marqueurs, filtres et mises à jour restent gérés par TH.GL. Le suivi automatique de la position du personnage n'est pas implémenté : cette carte ne lit pas le jeu et ne se connecte pas à ton compte NetEase. La carte officielle reste accessible séparément.</div><div class="card map-panel" style="margin-top:15px"><div class="map-toolbar"><div><span class="tag">CARTE COMMUNAUTAIRE INTÉGRÉE</span><h2 style="margin:12px 0 5px">Atlas du monde</h2><p class="muted small">Choisis une région, puis charge la carte interactive et ses filtres.</p></div><div class="map-controls"><select class="field" id="map-region" aria-label="Région de la carte">${optionsHtml}</select><button class="btn primary" id="load-map">Charger la carte</button></div></div><div id="map-frame-wrap" class="map-frame-wrap"><div class="map-consent"><div class="map-symbol">風</div><strong>Carte interactive prête</strong><p>Le contenu sera chargé depuis TH.GL. Ce fournisseur tiers pourra recevoir des informations techniques comme ton adresse IP et appliquer ses propres règles de confidentialité.</p><button class="btn primary" id="load-map-first">Afficher la carte</button></div></div><p class="map-credit"><a href="${selected.url}" target="_blank" rel="noopener">Ouvrir cette carte sur TH.GL ↗</a> · Carte par The Hidden Gaming Lair. <a href="https://www.wherewindsmeetgame.com/map/" target="_blank" rel="noopener">Carte officielle ↗</a></p></div><div class="section-head"><h2>Suivi personnel des découvertes</h2></div><div class="card"><p class="muted small">Pense-bête général indépendant des marqueurs TH.GL.</p>${checksHtml}</div><div class="section-head"><h2>Mon carnet de ${esc(selected.id==="central"?"Plaine centrale":selected.id==="hexi"?"Hexi":"Ruines Transdust")}</h2><span class="muted small">${notes.filter(n=>n.done).length}/${notes.length} trouvés</span></div><div class="card"><p class="muted small">Enregistre ici les lieux que tu veux retrouver. Ce sont des notes personnelles associées à la région, pas des coordonnées ni des marqueurs superposés à la carte.</p><form id="map-note-form"><input class="field" name="title" placeholder="Nom du lieu ou de la découverte" required maxlength="100" style="margin:8px 0"><div class="form-row"><select class="field" name="category">${categoriesHtml}</select><input class="field" name="detail" placeholder="Détail ou repère (facultatif)" maxlength="240"></div><div class="action-row"><button class="btn primary">Ajouter à mon carnet</button></div></form><div class="list" style="margin-top:14px">${notesHtml}</div></div><p class="muted small">Le carnet suit la région sélectionnée et sera inclus dans tes sauvegardes JSON et la synchronisation compagnon lorsqu'elle sera configurée.</p>`;
}

function journal(){return `<div class="card"><h2>Journal d'aventure</h2><form id="journal-form"><textarea class="field" name="note" rows="4" placeholder="Qu'as-tu découvert aujourd'hui ?"></textarea><div class="action-row"><button class="btn primary">Enregistrer l'entrée</button></div></form><div class="section-head"><h2>Historique</h2></div>${data.journal.length?'<div class="list">'+[...data.journal].reverse().map(j=>`<div class="list-row"><span>${esc(j.note)}</span><span class="muted small">${esc(j.date)}</span></div>`).join('')+'</div>':'<div class="empty">Aucune entrée enregistrée.</div>'}</div>`;}
function builds(){const first=codexPaths[0];const pathOptions=codexPaths.map(p=>'<option value="'+esc(p.path)+'">'+esc(p.path)+'</option>').join("");const artOptions=first.arts.map(a=>'<option>'+esc(a)+'</option>').join("");const innerOptions=first.inner.map(a=>'<option>'+esc(a)+'</option>').join("");const templateOptions=buildTemplates.map((t,i)=>'<option value="'+i+'">'+esc(t.name)+'</option>').join("");return '<div class="card"><span class="tag">PLANIFICATEUR PERSONNEL</span><h2 style="margin:12px 0">Mes builds</h2><p class="muted small">Compose une configuration à partir des voies, arts martiaux et Inner Ways documentés dans l’encyclopédie. Tu peux partir d’un modèle sourcé ou construire ta propre combinaison.</p><form id="build-form"><label class="small muted">Modèle de départ (facultatif)</label><select class="field" id="build-template" style="margin:6px 0 12px"><option value="">Choisir un modèle…</option>'+templateOptions+'</select><input class="field" name="name" placeholder="Nom du build" required maxlength="80" style="margin:10px 0"><label class="small muted">Voie</label><select class="field" name="path" id="build-path" style="margin:6px 0 12px">'+pathOptions+'</select><div class="form-row"><div><label class="small muted">Art martial principal</label><select class="field" name="art1" id="build-art1">'+artOptions+'</select></div><div><label class="small muted">Art martial secondaire</label><select class="field" name="art2" id="build-art2">'+artOptions+'</select></div></div><label class="small muted">Inner Ways (sélection multiple)</label><select class="field" name="innerWays" id="build-inner" multiple size="4" style="margin:6px 0 12px">'+innerOptions+'</select><label class="small muted">Compétences mystiques / Omni-Weapon</label><input class="field" name="skills" placeholder="Ex. Cloud Steps, Contortion…" style="margin:6px 0 12px"><label class="small muted">Équipement, statistiques et notes</label><textarea class="field" name="details" rows="4" placeholder="Pièces d’équipement, affixes, rotation, points à tester…"></textarea><div class="action-row"><button class="btn primary">Enregistrer le build</button></div></form><div class="section-head"><h2>Configurations sauvegardées</h2></div>'+(data.builds.length?'<div class="grid">'+[...data.builds].reverse().map(b=>'<article class="card"><h3>'+esc(b.name)+'</h3>'+(b.path?'<span class="tag">'+esc(b.path)+'</span>':'')+'<p class="small">'+esc((b.arts||[]).join(" + ")||"Arts non renseignés")+'</p>'+(b.innerWays&&b.innerWays.length?'<p class="muted small">Inner Ways : '+esc(b.innerWays.join(", "))+'</p>':'')+(b.skills?'<p class="muted small">Compétences : '+esc(b.skills)+'</p>':'')+(b.details?'<p class="small">'+esc(b.details)+'</p>':'')+'</article>').join("")+'</div>':'<div class="empty">Aucun build enregistré.</div>')+'</div>';}
const bossData=[
{name:"Feng Ruzhi",region:"Kaifeng",area:"Roaring Sands · Verdant Hill Village (après Heavenfall)",version:"1.1",note:"La version boss mondial apparaît après avoir terminé la campagne Heavenfall ; le repère précis indiqué par les guides est Verdant Hill Village.",strategy:"La mécanique prioritaire est la boule de soie : certaines attaques à lueur jaune peuvent te la voler. Si cela arrive, cesse immédiatement d’échanger des coups, fonce vers la boule et élimine le garde avant la fin du compte à rebours affiché. Garde de l’endurance pour cette récupération. Esquive la tentative de vol plutôt que de chercher à la bloquer ; sur les longues chaînes, attends la fin du combo pour punir.",source:"https://allthings.how/feng-ruzhi-in-where-winds-meet-location-mechanics-and-rewards/",sourceLabel:"Guide Feng Ruzhi · All Things How (15 décembre 2025)"},
{name:"Wolf Maiden",region:"Kaifeng",area:"Desperation Ridge · Granary of Plenty",version:"Lancement",note:"Repère de localisation communautaire ; consulter le Journal en jeu pour le marqueur exact.",strategy:"C’est une rencontre nocturne : si elle n’apparaît pas, reviens de nuit et vérifie le Journal. En combat, privilégie la lecture de ses courtes charges et estocs : dévie ou esquive parfaitement, puis punis avec un combo bref avant sa prochaine ruée. Évite de t’enfermer dans une longue animation face à sa mobilité.",source:"https://npa-www-procd-a0f2e2h7hfdkfjgs.eastus-01.azurewebsites.net/where-winds-meet-guide/tips-guides/all-bosses-and-how-to-beat-them/",sourceLabel:"Guide World Boss · PlayerAuctions (19 novembre 2025)"},
{name:"Twin Lions",region:"Kaifeng",area:"Sud de Gracetown · Granary of Plenty",version:"Lancement",note:"Repère de localisation communautaire ; consulter le Journal en jeu pour le marqueur exact.",strategy:"Garde les deux lions dans ton champ de vision : leurs attaques de zone peuvent se chevaucher. Utilise les compétences de zone pour toucher les deux cibles, mais déplace-toi dès que leurs zones d’impact se superposent afin de ne pas subir les deux frappes.",source:"https://npa-www-procd-a0f2e2h7hfdkfjgs.eastus-01.azurewebsites.net/where-winds-meet-guide/tips-guides/all-bosses-and-how-to-beat-them/",sourceLabel:"Guide World Boss · PlayerAuctions (19 novembre 2025)"},
{name:"Ghost Master",region:"Kaifeng",area:"Ouest de Mistveil Forest · Granary of Plenty",version:"Lancement",note:"Repère de localisation communautaire ; combat en groupe recommandé par certains guides.",strategy:"La brume toxique de Mistveil Forest doit d’abord être levée en terminant la chaîne de quêtes Ephemeral Blight. Pendant le combat, Meridian Touch peut dissiper ses projectiles ; utilise ensuite ta mobilité pour réduire rapidement la distance et maintenir la pression au corps-à-corps.",source:"https://npa-www-procd-a0f2e2h7hfdkfjgs.eastus-01.azurewebsites.net/where-winds-meet-guide/tips-guides/all-bosses-and-how-to-beat-them/",sourceLabel:"Guide World Boss · PlayerAuctions (19 novembre 2025)"},
{name:"Nameless General",region:"Kaifeng",area:"Martial Temple · Jadewood Court",version:"Lancement",note:"Le temple des arts martiaux est le repère de localisation indiqué par les guides.",strategy:"En première phase, sa garde ou son bouclier absorbe les échanges frontaux : privilégie les arts martiaux qui brisent la garde ou l’endurance. En deuxième phase, contourne-le et attaque ses flancs ; ses frappes frontales sont particulièrement dangereuses.",source:"https://npa-www-procd-a0f2e2h7hfdkfjgs.eastus-01.azurewebsites.net/where-winds-meet-guide/tips-guides/all-bosses-and-how-to-beat-them/",sourceLabel:"Guide World Boss · PlayerAuctions (19 novembre 2025)"},
{name:"Puppeteer — Sheng Wu",region:"Qinghe",area:"Au sud du waypoint du campfire · Verdant Wilds",version:"Lancement",note:"Porte une hallebarde ; le guide communautaire décrit une attaque de poussée dorée et une séquence de marionnettes.",strategy:"Priorise la jauge de Qi : les parades et esquives bien timées la font baisser, puis l’exécution offre une fenêtre de dégâts sûre. Lors de l’intermède de la deuxième phase, élimine les marionnettes tout en évitant ses tirs ; ne gaspille pas tes attaques sur le boss pendant cette séquence.",source:"https://allthings.how/how-to-beat-puppeteer-sheng-wu-in-where-winds-meet/",sourceLabel:"Guide détaillé de Sheng Wu · All Things How"},
{name:"Sleeping Daoist",region:"Qinghe",area:"Jadebrook Mountain · Sundara Land",version:"Lancement",note:"Boss monté sur un âne ; projectiles à distance, coups de sabot et seconde phase dans une arène de rêve.",strategy:"Reste à moyenne ou longue portée et provoque ses salves de projectiles : dévie-les pour vider sa jauge de Qi. Profite d’une ouverture Cloud Steps pour approcher, infliger un court combo ou un finisher, puis recule. Évite de rester derrière l’âne à cause de son coup de sabot jaune. En phase 2, privilégie la survie et la lecture des salves plutôt que les dégâts forcés. Le compagnon Yi Dao peut aider à interrompre et soigner ; garde-le en vie pendant la première phase.",source:"https://allthings.how/where-winds-meet-sleeping-daoist-boss-strategy-and-location/",sourceLabel:"Guide détaillé Sleeping Daoist · All Things How (26 novembre 2025)"},
{name:"Puppeteer — Curtaincall",region:"Qinghe",area:"Petite île au nord-ouest de Sundara Land",version:"Lancement",note:"Repère géographique communautaire ; vérifier le marqueur dans le Journal.",strategy:"Ses attaques chargées rouges sont lentes et offrent une bonne occasion de déflexion parfaite pour accélérer sa jauge de déséquilibre. Pour ses estocs rapides, décale-toi latéralement plutôt que de reculer en ligne droite ; ne prolonge le combo qu’après sa récupération.",source:"https://npa-www-procd-a0f2e2h7hfdkfjgs.eastus-01.azurewebsites.net/where-winds-meet-guide/tips-guides/all-bosses-and-how-to-beat-them/",sourceLabel:"Guide des boss · PlayerAuctions (mécaniques de Curtaincall)"},
{name:"Earth Fiend Deity",region:"Qinghe",area:"Route entre Witherwilds et Peace Bell Tower · Moonveil Mountain",version:"Lancement",note:"Repère géographique communautaire ; vérifier le marqueur dans le Journal.",strategy:"Garde Cloud Steps pour le tourbillon qui aspire vers le centre : déclenche-le pendant la canalisation pour interrompre l’attaque, au lieu de le dépenser dès l’engagement. Surveille les séries de sauts (le premier impact ne clôt pas toujours la séquence), défends-toi aussi contre les lames de vent à distance et esquive le jaillissement après son enfouissement si tu n’es pas sûr du timing de déflexion. Exploite ensuite la fenêtre de récupération ou l’Execute.",source:"https://wherewindsmeethandbook.com/bosses/earth-fiend-deity/",sourceLabel:"Guide Earth Fiend Deity · Where Winds Meet Handbook (1 octobre 2026)"},
{name:"Snake Doctor",region:"Qinghe",area:"Grotte souterraine à l'ouest d'Encircling Lake · Moonveil Mountain",version:"Lancement",note:"Le repère communautaire indique une grotte souterraine.",strategy:"Reste autant que possible à portée de mêlée : à distance, ses projectiles et zones empoisonnées deviennent plus difficiles à gérer. Dévie ses enchaînements de bâton et ses attaques rouges pour épuiser sa posture, puis utilise l’Execute lorsqu’il est déséquilibré. Son attaque dorée qui projette trois serpents en large éventail ne se pare pas : désengage-toi ou esquive largement sur le côté. Évite les nuages de poison et soigne-toi dans une vraie fenêtre de répit.",source:"https://allthings.how/snake-doctor-world-boss-guide-where-winds-meet/",sourceLabel:"Guide détaillé Snake Doctor · All Things How (19 novembre 2025)"},
{name:"Yi Dao",region:"Qinghe",area:"Près d'un arbre et d'un bâtiment brûlé · Moonveil Mountain",version:"Lancement",note:"Repère géographique communautaire ; vérifier le marqueur dans le Journal.",strategy:"Le duel de Dreamscape se débloque après la fin de l’histoire principale de Qinghe (Chapitre 1). Garde une distance moyenne : trop loin, tu lui offres l’occasion de fondre sur toi. Dévie ses attaques rouges, notamment le saut lorsque sa lame flashe en rouge, et esquive entièrement ses attaques dorées. Ses longues séries peuvent être parées coup par coup ; attends la fin de l’enchaînement ou un déséquilibre avant d’engager un combo. Celestial Seize peut interrompre certaines attaques de zone en lui arrachant son épée.",source:"https://allthings.how/yi-dao-in-where-winds-meet-how-the-killerblade-fight-works/",sourceLabel:"Guide détaillé Yi Dao · All Things How (22 novembre 2025)"},
{name:"Coffin Master",region:"Qinghe",area:"Mercyheart Monastery",version:"1.3",note:"Combat avec cercueil ; l'aperçu de version confirme la zone.",strategy:"Le guide anglophone emploie l’ancien nom « Coffin Keeper Lord » pour ce combat. Il possède une grande réserve de vie et des frappes lentes mais puissantes : équipe des arts martiaux à forte rupture de Qi, interromps ses chaînes lorsque c’est possible et utilise le finisher pour prolonger la fenêtre de vulnérabilité.",source:"https://npa-www-procd-a0f2e2h7hfdkfjgs.eastus-01.azurewebsites.net/where-winds-meet-guide/tips-guides/all-bosses-and-how-to-beat-them/",sourceLabel:"Guide World Boss · PlayerAuctions (19 novembre 2025), nom historique « Coffin Keeper Lord »"},
{name:"Drunk Martial Artist",region:"Kaifeng",area:"Southwatch Height",version:"1.3",note:"Style Drunken Fist ; l'aperçu officiel de version indique Southwatch Height.",strategy:"Son style ivre rend le rythme irrégulier : ne cherche pas à interrompre chaque mouvement. Laisse passer sa rafale, attends son trébuchement ou sa courte pause, place quelques attaques, puis reprends de la distance avant sa prochaine ruée imprévisible.",source:"https://npa-www-procd-a0f2e2h7hfdkfjgs.eastus-01.azurewebsites.net/where-winds-meet-guide/tips-guides/all-bosses-and-how-to-beat-them/",sourceLabel:"Guide World Boss · PlayerAuctions (19 novembre 2025)"},
{name:"Wandering Ark",region:"Hexi",area:"Straying Steed Sands · Jade Gate Pass",version:"1.4",note:"Boss caché dans la tempête de sable ; suivre les cloches de chameau pour traverser la tempête.",strategy:"Phase 1 : les trois salves de flèches d’ouverture ne se défléchissent pas, sprinte et esquive vers l’avant. Vise ensuite les quatre branches desséchées de lune sur ses pattes : ce sont les points faibles de cette phase ; les coups sur le corps ne font pas avancer le combat. Esquive plutôt que de parer les piétinements et le bellyflop. Phase 2 : évite latéralement la charge, éloigne-toi des ronces et projectiles, puis esquive Moonfall. Dès que le projectile lunaire touche le sol, utilise Reverse sur lui pour le renvoyer au boss, le faire tomber et frapper le point faible exposé.",source:"https://allthings.how/where-winds-meet-wandering-ark-boss-fight-made-simple/",sourceLabel:"Guide détaillé Wandering Ark · All Things How (6 mars 2026)"},
{name:"Moongazing Maiden",region:"Hexi",area:"Jade-Mirrored Spring · Liangzhou",version:"1.5",note:"Le combat comporte une transition de phase avec une zone sûre sous le champ de foudre ; lis le signal et utilise l’interaction de saut.",strategy:"Phase 1 : apprends les chaînes complètes d’épée et de queue et dévie-les avant de chercher les dégâts. Lors de la transition électrique, rejoins rapidement la zone sûre sous elle avec l’interaction de Cloud Leap ; rester en l’air ou à l’extérieur ne suffit pas. En phase 2, les parades chargent l’épée : utilise ensuite l’attaque lourde pour libérer les vagues d’énergie. Sur la chaîne fouet, respecte la petite pause après les quatre premières frappes avant de parer le coup de queue. Éloigne-toi des flaques et des barrages de foudre au lieu d’essayer de tout parer.",source:"https://www.reddit.com/r/WhereWindsMeet/comments/1sk6qif/moongazing_maiden/",sourceLabel:"Retour détaillé de joueurs · r/WhereWindsMeet (mécaniques communautaires, à confirmer en jeu)"},
{name:"Everdeer",region:"Hexi",area:"Steed's Pass · Liangzhou",version:"1.5",note:"Les guides mentionnent une préparation de quête qui peut réduire le nombre de phases ; vérifier le journal et les conditions sur ta version.",strategy:"Quand Deer's Blessing fait apparaître des orbes verts, cesse de poursuivre le boss et détruis-en autant que possible avant la fin de la canalisation : ceux qui restent lui rendent des soins. Beaucoup de ses attaques couvrent une large zone ou viennent du sol ; privilégie les esquives et attends la fin des chaînes multi-coups avant de reprendre l’offensive. Une fois les orbes maîtrisés, maintiens une pression régulière pendant ses fenêtres de récupération.",source:"https://www.cheatbook.de/files/wherewindsmeet.htm",sourceLabel:"Fiche communautaire Everdeer · Cheatbook (mécaniques à recouper en jeu)"},
{name:"Pocketrupt Circus",region:"Hexi",area:"Clear-Dew Terrace · Liangzhou",version:"1.5",note:"Rencontre contre deux adversaires aux rythmes différents.",strategy:"Traite les deux adversaires différemment. Le plus grand a des attaques lentes et lisibles : utilise-les pour pratiquer les parades, mais esquive ses attaques à lueur dorée. Le plus petit est plus chaotique et met la pression avec des attaques de fumée : garde de la distance au lieu de rester collé à lui. Punis le grand entre ses attaques, sans t’entêter lorsque le petit approche. Le guide communautaire recommande Flute of the Tides pour infliger des dégâts à distance de façon contrôlée.",source:"https://www.cheatbook.de/files/wherewindsmeet.htm",sourceLabel:"Fiche communautaire Pocketrupt Circus · Cheatbook (mécaniques à recouper en jeu)"},
{name:"Snowplum Requiem",region:"Hexi",area:"Marsh Plain · Qinchuan",version:"1.6",note:"Boss mondial de Qinchuan. Les guides détaillés retrouvés portent sur l’épreuve Hero’s Realm à 10 joueurs ; leurs mécaniques ne sont pas transposées au combat mondial.",guideStatus:"Conseil du combat mondial en attente : ne pas confondre avec la version Hero’s Realm à 10 joueurs."},
{name:"Gilded Lament",region:"Kaifeng",area:"Kunning Hall · Imperial Palace",version:"1.7",note:"Zone du palais à débloquer. Les séquences vidéo détaillées retrouvées proviennent du serveur de test ; aucune tactique n’est présentée comme vérifiée sur le serveur live.",guideStatus:"Conseil détaillé suspendu : les seules séquences de combat détaillées retrouvées sont explicitement issues du serveur de test."},
{name:"Cat Emperor",region:"Kaifeng",area:"Rear Garden · Imperial Palace · étang du Inner Garden",version:"1.7",note:"Déclenchement lié à The Grand Carp : parler à Li Jingwei près de l’étang, régler l’heure sur You puis pêcher.",strategy:"Le Cat Emperor ne peut pas être déséquilibré : sa jauge de Qi est inépuisable. Ne construis donc pas ton plan autour d’un Execute. Reste proche pour que tes contres touchent, dévie ses longues séries de coups de poisson et profite des pauses. Esquive le bond d’ouverture ; en phase 2, surveille le roulé suivi d’une charge et éloigne-toi du jet d’eau à courte portée. Si tu lui infliges des dégâts de feu, attends-toi à son coup au sol et replace-toi.",source:"https://allthings.how/where-winds-meet-cat-emperor-how-to-spawn-and-beat-the-boss/",sourceLabel:"Guide détaillé Cat Emperor · All Things How (29 mai 2026)"},
{name:"Ci & Cuo",region:"Hidden Mountain",area:"Suixiang",version:"2.0",note:"Combat contre des automates ; viser les parties vulnérables plutôt que frapper sans discernement.",strategy:"Pour l’épreuve d’épée « Segmented Puppets » (niveau 96, cinq joueurs), les marionnettes doivent être appariées par couleurs opposées : le joueur marqué attire une marionnette vers sa paire de couleur contraire. Si aucune paire ne reste, utilise une estrade secondaire. Ces consignes concernent cette épreuve d’équipe, pas nécessairement le boss en monde ouvert.",source:"https://allthings.how/where-winds-meet-lvl-96-sword-trial-guide-ironheart-centipede-and-ci-and-cuo/",sourceLabel:"Épreuve Segmented Puppets · All Things How"},
{name:"Ironheart Centipede",region:"Hidden Mountain",area:"Suixiang",version:"2.0",note:"Mécanisme mohiste avec brume toxique ; observer les mouvements des segments et les points faibles.",strategy:"Dans l’épreuve d’épée « Segmented Puppets » (niveau 96, cinq joueurs), les déflexions des attaques rouges vident la jauge de parade et provoquent le désarmement. Après la chute des quatre bras, deux joueurs détruisent les restes du mille-pattes et deux autres interrompent sa charge. Les flaques dorées de poison doivent être esquivées. Attention : cette stratégie est propre à l’épreuve, dont les mécaniques diffèrent du boss mondial.",source:"https://allthings.how/where-winds-meet-lvl-96-sword-trial-guide-ironheart-centipede-and-ci-and-cuo/",sourceLabel:"Épreuve Segmented Puppets · All Things How"},
{name:"Inkpincer Scorpion",region:"Hidden Mountain",area:"Suixiang",version:"2.1",note:"Compétence mystique Contortion requise ; briser sa garde.",strategy:"Débloque la compétence mystique Contortion avant de venir. Le Scorpion est blindé et reste ancré : concentre-toi sur la rupture de sa garde plutôt que de poursuivre un échange de dégâts classique.",source:"https://senseos.gg/guides/where-winds-meet/wwm-world-bosses/",sourceLabel:"Résumé des mécaniques d’après la lettre de développeurs du 21 août · SenseOS"},
{name:"Cloudclutch Serpent",region:"Hidden Mountain",area:"Suixiang",version:"2.1",note:"Contortion requise ; rester mobile et suivre ses déplacements.",strategy:"Débloque Contortion avant l’affrontement. Contrairement au Scorpion blindé, le Serpent est constamment mobile : garde-le en vue, suis ses déplacements et adapte ton placement au lieu de rester immobile à attendre.",source:"https://senseos.gg/guides/where-winds-meet/wwm-world-bosses/",sourceLabel:"Résumé des mécaniques d’après la lettre de développeurs du 21 août · SenseOS"},
{name:"Golden Colossus Taicu",region:"Hidden Mountain",area:"Heaven's Threshold",version:"2.2",note:"Attirer ses frappes vers les noyaux de formation, puis grimper et viser les articulations lorsqu'une ouverture apparaît.",strategy:"Fais frapper le colosse sur les noyaux de formation disséminés dans l’arène. Quand une attaque crée une ouverture, grimpe sur lui et cible ses articulations, une par une.",source:"https://senseos.gg/guides/where-winds-meet/wwm-world-bosses/",sourceLabel:"Résumé des mécaniques d’après la lettre de développeurs du 19 septembre · SenseOS"},
{name:"Goshawk",region:"Hidden Mountain",area:"Heaven's Threshold",version:"2.2",note:"Les coups de marteau répandent des étincelles et réduisent l'espace sûr ; surveiller le sol autant que le boss.",strategy:"Ne fixe pas uniquement le marteau : chaque impact répand des étincelles métalliques qui réduisent progressivement les zones sûres. Repère leur propagation et replace-toi avant que l’espace disponible ne se referme.",source:"https://senseos.gg/guides/where-winds-meet/wwm-world-bosses/",sourceLabel:"Résumé des mécaniques d’après la lettre de développeurs du 19 septembre · SenseOS"},
{name:"Tidewatcher",region:"Qingzhou",area:"Eastern Peak",version:"2.3",note:"Combattant sur échasses avec lance ; en deuxième phase, franchir les vagues venant de derrière avec les compétences de légèreté.",strategy:"Ses échasses, rotations et pas de danse rendent les attaques de lance difficiles à lire. En deuxième phase, surveille aussi l’arrière de l’arène : des vagues arrivent dans ton dos et doivent être franchies avec les compétences de légèreté.",source:"https://senseos.gg/guides/where-winds-meet/wwm-world-bosses/",sourceLabel:"Lettre de développeurs V2.3, partie 2 · résumé SenseOS"},
{name:"Old Raftsman",region:"Qingzhou",area:"Berges de Qingzhou",version:"2.3",note:"Combat sur des radeaux dérivants ; distinguer les feintes des coups lourds du bâton.",strategy:"Le duel se déroule sur des radeaux dérivants et la caméra passe parfois en vue latérale. Son bâton alterne feintes et vrais coups lourds ; il peut aussi boire et adopter un style ivre. Attends de confirmer la vraie frappe avant de contre-attaquer.",source:"https://senseos.gg/guides/where-winds-meet/wwm-world-bosses/",sourceLabel:"Lettre de développeurs V2.3, partie 2 · résumé SenseOS"},
{name:"Shuttlecock Champion",region:"Qingzhou",area:"Dragonfall Camp · Eastern Peak",version:"2.3",note:"Attraper le volant rouge en vol pour déclencher le combat ; combat rapproché avec coups de pied et projections.",strategy:"Le combat commence en attrapant le volant rouge à plumes pendant son vol. Elle combat sans arme et reste au contact avec coups de pied et projections : garde de l’espace et évite de lancer une longue animation au mauvais moment.",source:"https://senseos.gg/guides/where-winds-meet/wwm-world-bosses/",sourceLabel:"Lettre de développeurs V2.3, partie 2 · résumé SenseOS"},
{name:"Wayfarer Bingshen",region:"Hutuo",area:"Moonveil Knoll",version:"2.4",note:"Ses signaux rouges et jaunes mettent à l’épreuve les parades, déflexions et esquives ; lis chaque indication avant de répondre.",strategy:"Aperçu pré-lancement publié le 12 novembre : il décrit des enchaînements rapides, une courte fenêtre de riposte et des dernières phases exigeantes. La recommandation éditoriale est de défendre pendant toute la séquence et de ne riposter qu’à la fin ; confirme ces indications en jeu, car ce guide précède la sortie de Hutuo.",source:"https://gamemarket.gg/news/where-winds-meet/where-winds-meet-bosses-where-to-find-every-world-boss",sourceLabel:"Aperçu pré-lancement Hutuo · GameMarket.gg (12 novembre 2026)"},
{name:"Yelu Abuli",region:"Hutuo",area:"Autel près de la rivière Hutuo",version:"2.4",note:"Shamane khitane, elle invoque des rituels et des métamorphoses (aigle, loup et feu follet du renard) ; observe la forme avant d’adapter ta défense.",strategy:"Aperçu pré-lancement publié le 12 novembre : il présente trois formes — aigle, loup et feu follet du renard — et recommande d’adapter son placement à chaque forme et de maintenir la pression sur le rituel. Les timings et les réponses précises restent à confirmer en jeu.",source:"https://gamemarket.gg/news/where-winds-meet/where-winds-meet-bosses-where-to-find-every-world-boss",sourceLabel:"Guide Hutuo · GameMarket.gg (12 novembre 2026)"}
];
function bosses(){return `<div class="notice">Catalogue des <b>31 boss mondiaux</b> recensés jusqu’à la mise à jour 2.4 (13 novembre 2026), dont <b>${bossData.filter(x=>x.strategy).length} fiches de combat sourcées</b>. Deux combats restent volontairement sans tactique : les sources détaillées retrouvées ne correspondent pas à leur version mondiale en direct. Le boss de campagne Xiao Han est présenté séparément plus bas : il n’est pas inclus dans ce total. Les lieux sont des repères de région, pas des coordonnées GPS.</div><div class="card" style="margin-top:15px"><div class="grid" style="grid-template-columns:1fr 190px"><input class="field" id="boss-search" placeholder="Rechercher un boss ou une zone…"><select class="field" id="boss-region"><option value="">Toutes les régions</option>${[...new Set(bossData.map(x=>x.region))].map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><p class="muted small" id="boss-count" style="margin:12px 0 0">${bossData.length} boss recensés</p></div><div class="grid" id="boss-list" style="grid-template-columns:repeat(auto-fit,minmax(245px,1fr));margin-top:14px">${bossData.map((b,i)=>`<article class="card boss-card" data-region="${esc(b.region)}" data-search="${esc((b.name+' '+b.region+' '+b.area+' '+b.note+' '+(b.strategy||'')+' '+(b.sourceLabel||'')).toLowerCase())}"><div class="row" style="display:flex;justify-content:space-between;gap:8px"><span class="tag">${esc(b.region)}</span><span class="muted small">v${esc(b.version)}</span></div><h2 style="margin:12px 0 5px">${esc(b.name)}</h2><div class="muted small">⌖ ${esc(b.area)}</div><p class="small">${esc(b.note)}</p>${b.strategy?`<details class="boss-strategy"><summary>Conseil de combat sourcé</summary><p class="small">${esc(b.strategy)}</p><a class="small" href="${esc(b.source)}" target="_blank" rel="noopener">${esc(b.sourceLabel)} ↗</a></details>`:`<p class="muted small">${esc(b.guideStatus||"Conseil détaillé à compléter après vérification d’une source adaptée au combat mondial.")}</p>`}<button class="btn" data-boss-note="${i}">Ajouter mes notes</button></article>`).join('')}</div><div class="card" style="margin-top:18px"><h2>Boss de campagne — Hutuo River</h2><p><b>Xiao Han</b> · Général khitan protégé par une armure surnaturelle forgée dans le sang. Il s’agit d’un boss de campagne, distinct des boss mondiaux listés ci-dessus ; les détails de combat restent à documenter.</p><p class="muted small">Source de roster : feuille de route Hutuo du 4 novembre 2026, relayée dans le guide communautaire sourcé.</p></div><div class="card" style="margin-top:18px"><h2>Repères de combat</h2><p class="small">Les guides communautaires décrivent généralement les attaques rouges comme des signaux de parade parfaite et les attaques dorées comme des signaux d'esquive. Vérifie toujours le tutoriel et les animations du combat concerné : ce repère n'est pas une règle universelle pour chaque boss.</p><div class="action-row"><a class="btn" href="https://www.wherewindsmeetgame.org/guides/where-winds-meet-bosses" target="_blank" rel="noopener">Liste des boss et distinctions ↗</a><a class="btn" href="https://wherewindsmeet.org/guides/hutuo" target="_blank" rel="noopener">Détails de la mise à jour Hutuo ↗</a><a class="btn" href="https://senseos.gg/wiki/where-winds-meet/versions/" target="_blank" rel="noopener">Historique des versions ↗</a></div></div><div class="card" style="margin-top:18px"><h2>Mon carnet de boss</h2><form id="journal-form"><input class="field" name="noteTitle" placeholder="Nom du boss (facultatif)" style="margin:8px 0"><textarea class="field" name="note" rows="3" placeholder="Attaques observées, timing, stratégie qui fonctionne…"></textarea><div class="action-row"><button class="btn primary">Enregistrer mes notes</button></div></form></div>`;}

const codexPaths=[
{path:"Bellstrike - Splendor",family:"Bellstrike",arts:["Nameless Sword","Nameless Spear"],inner:["Sword Morph","Mountain’s Might","Battle Anthem"],since:"Avant 1.4"},
{path:"Bellstrike - Umbra",family:"Bellstrike",arts:["Strategic Sword","Heavenquaker Spear"],inner:["Wolfchaser’s Art","Sword Horizon","Fivefold Bleed","Insightful Strike"],since:"Avant 1.4"},
{path:"Silkbind - Jade",family:"Silkbind",arts:["Vernal Umbrella","Inkwell Fan"],inner:["Thunderous Bloom","Star Reacher","Blossom Barrage"],since:"Avant 1.4"},
{path:"Silkbind - Deluge",family:"Silkbind",arts:["Panacea Fan","Soulshade Umbrella"],inner:["Restoring Blossom","Esoteric Revival"],since:"Avant 1.4"},
{path:"Silkbind - Wings",family:"Silkbind",arts:["Museflow Waist Drum","Willowbend Fan"],inner:["Harmony Song","Zephyr Whispers","Melody of the Brush","Blade’s Will"],since:"2.3 · 15 octobre 2026"},
{path:"Stonesplit - Might",family:"Stonesplit",arts:["Thundercry Blade","Stormbreaker Spear"],inner:["Exquisite Scenery","Art of Resistance","Trapped Beast"],since:"Avant 1.4"},
{path:"Stonesplit - Strength",family:"Stonesplit",arts:["Snowparting Blade","Phalanxbane Blade"],inner:["Frost-Clad Night","Steadfast Devotion","Throat-Piercing Art"],since:"1.5 · 2 avril 2026"},
{path:"Bamboocut - Wind",family:"Bamboocut",arts:["Infernal Twinblades","Mortal Rope Dart"],inner:["Echoes of Oblivion","Vendetta","Riptide Reflex","Breaking Point"],since:"Avant 1.4"},
{path:"Bamboocut - Dust",family:"Bamboocut",arts:["Everspring Umbrella","Unfettered Rope Dart"],inner:["Phantom Rally","Towline Sweep","Light Anew"],since:"1.4 · 6 mars 2026"},
{path:"Bamboocut - Kite",family:"Bamboocut",arts:["Heavenwill Gauntlets","Skygrasp Rope Dart"],inner:["Sky Gripped"],since:"2.0 · 23 juillet 2026"},
{path:"Bamboocut - Draught",family:"Bamboocut",arts:["Skystrike Gauntlets","Riven Twinblades"],inner:["Eonpour","Skyspeak","Mistwing","Volutefit"],since:"2.1 · 3 septembre 2026"}
];
const buildTemplates=[
{name:"DPS saignement · Strategic Sword + Heavenquaker Spear",path:"Bellstrike - Umbra",arts:["Strategic Sword","Heavenquaker Spear"],inner:["Wolfchaser’s Art","Sword Horizon","Fivefold Bleed","Insightful Strike"],skills:"Dragon’s Breath",details:"Route guide : applique 5 charges de saignement avec Strategic Sword, passe à Heavenquaker Spear pour Sober Sorrow et Soul Shaken, utilise Dragon’s Breath, puis reviens à Strategic Sword pour la boucle de dégâts. À adapter à ton équipement et à la version.",source:"https://www.cheatbook.de/files/wherewindsmeet.htm"},
{name:"Débutant · Nameless Sword + Nameless Spear",path:"Bellstrike - Splendor",arts:["Nameless Sword","Nameless Spear"],inner:["Sword Morph","Mountain’s Might","Battle Anthem"],skills:"",details:"Configuration de départ axée sur des fondamentaux lisibles et une bonne portée. À personnaliser selon tes talents et ton équipement.",source:"https://www.cheatbook.de/files/wherewindsmeet.htm"},
{name:"Agressif · Infernal Twinblades + Mortal Rope Dart",path:"Bamboocut - Wind",arts:["Infernal Twinblades","Mortal Rope Dart"],inner:["Echoes of Oblivion","Vendetta","Riptide Reflex","Breaking Point"],skills:"",details:"Association agressive qui récompense le maintien au corps-à-corps et une bonne gestion de l’espacement. À éviter si tu subis encore les contre-combos.",source:"https://www.cheatbook.de/files/wherewindsmeet.htm"},
{name:"Soutien · Vernal Umbrella + Inkwell Fan",path:"Silkbind - Jade",arts:["Vernal Umbrella","Inkwell Fan"],inner:["Thunderous Bloom","Star Reacher","Blossom Barrage"],skills:"",details:"Paire de soutien et de contrôle à distance. Le guide communautaire la cite comme option de jeu plus sûre ; adapte les passifs à ton rôle.",source:"https://www.cheatbook.de/files/wherewindsmeet.htm"},
{name:"Soin · Soulshade Umbrella + Panacea Fan",path:"Silkbind - Deluge",arts:["Soulshade Umbrella","Panacea Fan"],inner:["Restoring Blossom","Esoteric Revival"],skills:"",details:"Paire orientée soins et soutien d’équipe. Vérifie les compétences et Inner Ways requis avant de reproduire une rotation exacte.",source:"https://www.cheatbook.de/files/wherewindsmeet/"},
];
const codexEntries=[];
for(const p of codexPaths){
 codexEntries.push({kind:"Voie",name:p.path,subtitle:p.family+" · "+p.since,description:"Arts martiaux : "+p.arts.join(" et ")+". Inner Ways nommés : "+p.inner.join(", ")+". Une voie associe deux arts martiaux, ses passifs et son équipement.",source:"https://senseos.gg/guides/where-winds-meet/wwm-paths-explained/"});
 p.arts.forEach(a=>codexEntries.push({kind:"Art martial",name:a,subtitle:p.path,description:"Art martial associé à la voie "+p.path+". Les sources publiques consultées ne donnent pas toujours la méthode d’obtention ; aucune méthode non confirmée n’est inventée ici.",source:"https://senseos.gg/guides/where-winds-meet/wwm-weapons-and-how-to-get-them/"}));
 p.inner.forEach(a=>codexEntries.push({kind:"Inner Way",name:a,subtitle:p.path,description:"Technique passive citée pour "+p.path+". Les publications ne donnent pas systématiquement tous les effets par palier ; cette entrée confirme son association, pas un effet non publié.",source:"https://senseos.gg/guides/where-winds-meet/wwm-inner-ways-and-conversion/"}));
}
[
{name:"Contortion",kind:"Compétence",subtitle:"Compétence mystique · Qinghe",description:"À obtenir via la quête quotidienne Tiny Adventure à Qinghe (niveau 10). Indispensable pour accéder aux combats mondiaux Inkpincer Scorpion et Cloudclutch Serpent dans Hidden Mountain.",source:"https://senseos.gg/guides/where-winds-meet/wwm-mystic-skills/"},
{name:"Cloud Steps",kind:"Compétence",subtitle:"Compétence mystique · mobilité et interruption",description:"Peut interrompre le tourbillon aspirant d’Earth Fiend Deity en bondissant sur sa tête. Les fenêtres d’utilisation dépendent de l’attaque et du combat.",source:"https://npa-www-procd-a0f2e2h7hfdkfjgs.eastus-01.azurewebsites.net/where-winds-meet-guide/tips-guides/all-bosses-and-how-to-beat-them/"},
{name:"Meridian Touch",kind:"Compétence",subtitle:"Compétence mystique · interruption",description:"Mentionnée pour dissiper les projectiles de Ghost Master et interrompre certaines attaques énergétiques de boss de campagne.",source:"https://npa-www-procd-a0f2e2h7hfdkfjgs.eastus-01.azurewebsites.net/where-winds-meet-guide/tips-guides/all-bosses-and-how-to-beat-them/"},
{name:"Celestial Seize",kind:"Compétence",subtitle:"Compétence mystique · désarmement",description:"Peut désarmer ou interrompre certaines attaques chargées ; recommandée notamment contre Yi Dao. Ce n’est pas une interruption universelle.",source:"https://allthings.how/yi-dao-in-where-winds-meet-how-the-killerblade-fight-works/"},
{name:"Sky Tether",kind:"Compétence",subtitle:"Omni-Weapon · Gauntlets · Version 2.4",description:"Câble d’escalade lié aux Heavenwill Gauntlets. La route indiquée passe par la Wandering Tale Bound for the Sky dans Hidden Mountain, une fois les gantelets obtenus.",source:"https://senseos.gg/guides/where-winds-meet/wwm-weapons-and-how-to-get-them/"},
{name:"Silken Step",kind:"Compétence",subtitle:"Omni-Weapon · Waist Drum · Version 2.4",description:"Permet de glisser sur l’eau avec les vagues. La route indiquée passe par l’exploration Rhythm of the Waves à Qingzhou après obtention du Museflow Waist Drum.",source:"https://senseos.gg/guides/where-winds-meet/wwm-weapons-and-how-to-get-them/"},
{name:"Progression des Inner Ways",kind:"Système",subtitle:"Tier 0 à Tier 6",description:"Les Inner Ways sont des passifs associés aux voies. Leur progression utilise des Notes et va jusqu’au Tier 6. Les premières victoires contre les boss mondiaux donnent cinq Inner Way Note: Custom Chest selon les aperçus de version.",source:"https://senseos.gg/guides/where-winds-meet/wwm-inner-ways-and-conversion/"},
{name:"Conversion des Inner Ways",kind:"Système",subtitle:"Coût après essais gratuits",description:"Après les essais gratuits, une conversion coûte 500 Echo Jade selon les notes du 27 mai 2026. Le nombre exact d’essais gratuits n’est pas publié dans les sources consultées.",source:"https://senseos.gg/guides/where-winds-meet/wwm-inner-ways-and-conversion/"},
{name:"Armes et arts martiaux",kind:"Système",subtitle:"Référence Version 2.4",description:"Familles d’armes de mêlée recensées : épée, lance, éventail, ombrelle, corde-dard, doubles lames, Mo Blade, Heng Blade, gantelets et tambour. Les arcs sont classés à part.",source:"https://senseos.gg/guides/where-winds-meet/wwm-weapons-and-how-to-get-them/"},
{name:"Version 2.4 · Across Autumn Waters",kind:"Système",subtitle:"Mise à jour · 13 novembre 2026",description:"Ajoute la région Hutuo dans Hidden Mountain et les boss mondiaux Wayfarer Bingshen et Yelu Abuli. Aucun nouveau type d’arme ni art martial n’est indiqué ; deux compétences Omni-Weapon sont documentées.",source:"https://senseos.gg/wiki/where-winds-meet/versions/"}
].forEach(x=>codexEntries.push(x));

