function codexResults(entries){return entries.map(e=>'<article class="card codex-entry"><div class="section-head"><span class="tag">'+esc(e.kind)+'</span><span class="muted small">'+esc(e.subtitle)+'</span></div><h3>'+esc(e.name)+'</h3><p class="small">'+esc(e.description)+'</p><a href="'+esc(e.source)+'" target="_blank" rel="noopener">Consulter la source ↗</a></article>').join("")||'<div class="empty">Aucune entrée ne correspond à cette recherche.</div>';}

function codex(){return '<div class="card"><span class="tag">RÉFÉRENCE SOURCÉE · VERSION 2.4</span><h2>Encyclopédie du Jianghu</h2><p class="muted small">Voies, arts martiaux, Inner Ways, compétences et systèmes. Les associations sont documentées ; lorsqu’une source ne donne pas un effet ou un moyen d’obtention, la fiche le signale au lieu de l’inventer.</p><div class="form-row" style="margin:14px 0"><input class="field" id="codex-search" placeholder="Rechercher un nom, une arme, une voie…"><select class="field" id="codex-filter"><option value="">Toutes les catégories</option><option>Voie</option><option>Art martial</option><option>Inner Way</option><option>Compétence</option><option>Système</option><option>Région</option><option>Campagne</option><option>Boss mondial</option></select></div><div class="muted small" id="codex-count">'+codexEntries.length+' entrées référencées</div><div class="grid" id="codex-results" style="margin-top:12px">'+codexResults(codexEntries)+'</div><div class="notice" style="margin-top:16px">Couverture : 11 voies, 22 arts martiaux, 34 Inner Ways nommés, 12 régions, 14 campagnes et 31 boss mondiaux, plus 10 fiches de compétences et systèmes. Les catalogues détaillés d’objets, d’équipements et de toutes les compétences mystiques restent à compléter ; les entrées signalent les limites des sources.</div></div>';}
let currentView="overview";function whichCurrent(){return currentView;}function render(which="overview"){currentView=which;title.textContent=labels[which];document.querySelectorAll(".nav-item").forEach(b=>b.classList.toggle("active",b.dataset.view===which));view.innerHTML=({overview,map,quests,bosses,builds,codex,journal,account:()=>window.wwmAccountView?window.wwmAccountView():"<div class='card'>Compte compagnon en préparation.</div>"})[which]();bind();}
function bind(){const mapSelect=view.querySelector("#map-region");const loadMap=()=>{const id=mapSelect?.value||"central";const maps={central:{path:"Central%20Plain",url:"https://wherewindsmeet.th.gl/maps/Central%20Plain"},hexi:{path:"Hexi",url:"https://wherewindsmeet.th.gl/maps/Hexi"},transdust:{path:"Transdust%20Ruins",url:"https://wherewindsmeet.th.gl/maps/Transdust%20Ruins"}};const item=maps[id]||maps.central;data.mapRegion=id;save();const wrap=view.querySelector("#map-frame-wrap");if(wrap){wrap.innerHTML=`<iframe class="map-embed" src="https://wherewindsmeet.th.gl/embed/maps/${item.path}" title="Carte interactive Where Winds Meet — TH.GL" loading="lazy" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe>`;}const link=view.querySelector(".map-credit a");if(link)link.href=item.url;};const loadButton=view.querySelector("#load-map");if(loadButton)loadButton.onclick=loadMap;const firstLoad=view.querySelector("#load-map-first");if(firstLoad)firstLoad.onclick=loadMap;if(mapSelect)mapSelect.onchange=()=>{data.mapRegion=mapSelect.value;save();render("map");};view.querySelectorAll("[data-go]").forEach(b=>b.onclick=()=>render(b.dataset.go));view.querySelectorAll("[data-check]").forEach(b=>b.onchange=()=>{data.checks[b.dataset.check]=b.checked;data.checkUpdatedAt[b.dataset.check]=new Date().toISOString();save();});const mapNoteForm=view.querySelector("#map-note-form");if(mapNoteForm)mapNoteForm.onsubmit=e=>{e.preventDefault();const title=mapNoteForm.elements.namedItem("title").value.trim();if(!title)return;data.mapNotes.push({id:(window.crypto&&window.crypto.randomUUID?window.crypto.randomUUID():String(Date.now())+"-"+Math.random().toString(36).slice(2)),region:data.mapRegion||"central",title,category:mapNoteForm.elements.namedItem("category").value,detail:mapNoteForm.elements.namedItem("detail").value.trim(),done:false,createdAt:new Date().toISOString()});save();render("map");};view.querySelectorAll("[data-map-note-toggle]").forEach(b=>b.onchange=()=>{const note=data.mapNotes.find(n=>n.id===b.dataset.mapNoteToggle);if(note){note.done=b.checked;note.updatedAt=new Date().toISOString();save();render("map");}});view.querySelectorAll("[data-map-note-delete]").forEach(b=>b.onclick=()=>{data.deletedMapNoteIds.push(String(b.dataset.mapNoteDelete));data.mapNotes=data.mapNotes.filter(n=>n.id!==b.dataset.mapNoteDelete);save();render("map");});view.querySelectorAll("[data-quest]").forEach(b=>b.onchange=()=>{data.quests[+b.dataset.quest].done=b.checked;data.quests[+b.dataset.quest].updatedAt=new Date().toISOString();save();});view.querySelectorAll("[data-quest-add]").forEach(b=>b.onclick=()=>{const name=b.dataset.questAdd;if(!data.quests.some(q=>q.name===name)){data.quests.push({name,done:false,updatedAt:new Date().toISOString()});save();render("quests");}});const q=view.querySelector("#quest-form");if(q)q.onsubmit=e=>{e.preventDefault();data.quests.push({name:q.elements.namedItem("name").value,done:false});save();render("quests");};const j=view.querySelector("#journal-form");if(j)j.onsubmit=e=>{e.preventDefault();if(j.note.value.trim()){const heading=j.noteTitle?.value.trim();data.journal.push({note:(heading?heading+" — ":"")+j.note.value.trim(),date:new Date().toLocaleDateString("fr-FR")});save();render(whichCurrent());}};const cs=view.querySelector("#codex-search"),cf=view.querySelector("#codex-filter");const filterCodex=()=>{const q=(cs?.value||"").trim().toLocaleLowerCase("fr");const kind=cf?.value||"";const filtered=codexEntries.filter(e=>(!kind||e.kind===kind)&&(!q||[e.name,e.subtitle,e.description,e.kind].join(" ").toLocaleLowerCase("fr").includes(q)));const results=view.querySelector("#codex-results");if(results)results.innerHTML=codexResults(filtered);const count=view.querySelector("#codex-count");if(count)count.textContent=filtered.length+" / "+codexEntries.length+" entrées affichées";};if(cs)cs.oninput=filterCodex;if(cf)cf.onchange=filterCodex;const bs=view.querySelector("#boss-search"),br=view.querySelector("#boss-region");const filterBosses=()=>{let n=0;view.querySelectorAll(".boss-card").forEach(c=>{const ok=(!bs?.value||c.dataset.search.includes(bs.value.toLowerCase()))&&(!br?.value||c.dataset.region===br.value);c.hidden=!ok;if(ok)n++;});const count=view.querySelector("#boss-count");if(count)count.textContent=n+" boss affichés";};if(bs)bs.oninput=filterBosses;if(br)br.onchange=filterBosses;view.querySelectorAll("[data-boss-note]").forEach(btn=>btn.onclick=()=>{const boss=bossData[+btn.dataset.bossNote];const t=j?.querySelector("[name=noteTitle]");if(t)t.value=boss.name; j?.querySelector("[name=note]")?.focus();});const b=view.querySelector("#build-form");if(b){const path=b.querySelector("#build-path"),a1=b.querySelector("#build-art1"),a2=b.querySelector("#build-art2"),inner=b.querySelector("#build-inner"),template=b.querySelector("#build-template"),skills=b.elements.namedItem("skills"),details=b.elements.namedItem("details");const updateBuildChoices=()=>{const p=codexPaths.find(x=>x.path===path.value)||codexPaths[0];a1.innerHTML=p.arts.map(x=>'<option>'+esc(x)+'</option>').join("");a2.innerHTML=p.arts.map(x=>'<option>'+esc(x)+'</option>').join("");inner.innerHTML=p.inner.map(x=>'<option>'+esc(x)+'</option>').join("");};path.onchange=updateBuildChoices;if(template)template.onchange=()=>{const t=buildTemplates[Number(template.value)];if(!t)return;path.value=t.path;updateBuildChoices();a1.value=t.arts[0];a2.value=t.arts[1];Array.from(inner.options).forEach(o=>o.selected=t.inner.includes(o.value));skills.value=t.skills;details.value=t.details;b.elements.namedItem("name").value=t.name;};b.onsubmit=e=>{e.preventDefault();const selectedInner=Array.from(inner.selectedOptions).map(x=>x.value);const arts=[a1.value,a2.value].filter(Boolean);const chosen=template&&template.value!==""?buildTemplates[Number(template.value)]:null;data.builds.push({id:(window.crypto&&window.crypto.randomUUID?window.crypto.randomUUID():String(Date.now())+"-"+Math.random().toString(36).slice(2)),name:b.elements.namedItem("name").value.trim(),path:path.value,arts:arts,innerWays:selectedInner,skills:skills.value.trim(),details:details.value.trim(),source:chosen&&chosen.source||"",updatedAt:new Date().toISOString()});save();render("builds");};}if(window.wwmAccountBind)window.wwmAccountBind(view);}
document.querySelector("#nav").onclick=e=>{const b=e.target.closest("[data-view]");if(b)render(b.dataset.view);};
document.querySelector("#export-btn").onclick=()=>{const blob=new Blob([JSON.stringify(data,null,2)],{type:"application/json"});const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download="where-winds-meet-progression.json";a.click();URL.revokeObjectURL(a.href);};
document.querySelector("#import-btn").onclick=()=>document.querySelector("#import-file").click();
document.querySelector("#import-file").onchange=async e=>{
  const file=e.target.files&&e.target.files[0];if(!file)return;
  const state=document.querySelector("#save-state");
  try{
    const incoming=JSON.parse(await file.text());
    if(!incoming||typeof incoming!=="object"||Array.isArray(incoming))throw new Error("Le fichier doit contenir un objet JSON.");
    if(incoming.quests!==undefined&&!Array.isArray(incoming.quests))throw new Error("Le champ quests doit être une liste.");
    if(incoming.journal!==undefined&&!Array.isArray(incoming.journal))throw new Error("Le champ journal doit être une liste.");
    if(incoming.builds!==undefined&&!Array.isArray(incoming.builds))throw new Error("Le champ builds doit être une liste.");
    if(incoming.mapNotes!==undefined&&!Array.isArray(incoming.mapNotes))throw new Error("Le champ mapNotes doit être une liste.");
    if(incoming.deletedMapNoteIds!==undefined&&!Array.isArray(incoming.deletedMapNoteIds))throw new Error("Le champ deletedMapNoteIds doit être une liste.");
    if(incoming.checks!==undefined&&(!incoming.checks||typeof incoming.checks!=="object"||Array.isArray(incoming.checks)))throw new Error("Le champ checks doit être un objet.");
    const quests=new Map();
    (incoming.quests||[]).concat(data.quests||[]).forEach(q=>{if(q&&q.name){const key=String(q.name).trim().toLowerCase();if(key)quests.set(key,q);}});
    const journal=new Map();
    (incoming.journal||[]).concat(data.journal||[]).forEach(j=>{if(j)journal.set(String(j.date||"")+"|"+String(j.note||""),j);});
    const builds=new Map();
    (incoming.builds||[]).concat(data.builds||[]).forEach(v=>{if(v){const key=v.id?"id:"+String(v.id):"legacy:"+String(v.name||"")+"|"+String(v.details||"");const prev=builds.get(key);builds.set(key,prev?Object.assign({},prev,v):v);}});
    const mapNotes=new Map();(incoming.mapNotes||[]).concat(data.mapNotes||[]).forEach(n=>{if(n&&n.id)mapNotes.set(String(n.id),n);});data={...initial,...incoming,...data,quests:Array.from(quests.values()),journal:Array.from(journal.values()),checks:Object.assign({},incoming.checks||{},data.checks||{}),builds:Array.from(builds.values()),mapNotes:Array.from(mapNotes.values()).filter(n=>!(incoming.deletedMapNoteIds||[]).concat(data.deletedMapNoteIds||[]).includes(String(n.id))),deletedMapNoteIds:Array.from(new Set((incoming.deletedMapNoteIds||[]).concat(data.deletedMapNoteIds||[]).map(String))),checkUpdatedAt:Object.assign({},incoming.checkUpdatedAt||{},data.checkUpdatedAt||{}),mapRegion:data.mapRegion||incoming.mapRegion||"central"};
    save();render(currentView);
    if(state)state.textContent="● Sauvegarde importée et fusionnée";
  }catch(error){if(state)state.textContent="● Import impossible : "+error.message;}
  e.target.value="";
};
window.wwmDataApi={getData:()=>data,setData:value=>{data=value;},saveLocal:()=>{localStorage.setItem(KEY,JSON.stringify(data));render(currentView);},render:render,getView:()=>currentView};
let installPromptEvent=null;
const installButton=document.querySelector("#install-btn");
window.addEventListener("beforeinstallprompt",event=>{event.preventDefault();installPromptEvent=event;if(installButton)installButton.hidden=false;});
if(installButton)installButton.onclick=async()=>{if(!installPromptEvent)return;const promptEvent=installPromptEvent;installPromptEvent=null;try{await promptEvent.prompt();const choice=await promptEvent.userChoice;if(choice&&choice.outcome==="accepted"){installButton.textContent="Installé";}else{installButton.hidden=true;}}catch(error){installButton.hidden=true;}};
window.addEventListener("appinstalled",()=>{if(installButton){installButton.textContent="Installé";installButton.hidden=false;}});
render();
